content.css:
.reporting-gantt {
  display: block;
  user-select: none;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, sans-serif;
}
.reporting-gantt text {
  user-select: none;
  pointer-events: none;
}
.reporting-gantt g.resize-grip {
  opacity: 0;
  transition: opacity 120ms ease-out;
}
.reporting-gantt g.resize-grip:hover {
  opacity: 1;
}
.reporting-gantt g.drag-handles.dragging g.resize-grip {
  opacity: 1;
  transition: none;
}
.reporting-gantt g.resize-grip rect.swimlane-resize-handle,
.reporting-gantt g.resize-grip rect.activity-label-resize-handle {
  fill: #e8e8ec;
  stroke: #c0c0c0;
  stroke-width: 1;
}
.reporting-gantt g.resize-grip circle.grip-dot {
  pointer-events: none;
}
